import{_ as t,o as a,c as s,a2 as d}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"调试手册","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/debug-handbook.md","filePath":"zh/dev/debug-handbook.md"}'),o={name:"zh/dev/debug-handbook.md"};function i(c,e,n,l,r,p){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="调试手册" tabindex="-1">调试手册 <a class="header-anchor" href="#调试手册" aria-label="Permalink to &quot;调试手册&quot;">​</a></h1><p>从一台 OCOS 机器上提取证据的完整实战指南：串口捕获、内核 日志环、崩溃转储与寄存器快照，以及 —— 最重要的一 切 —— 在一切看起来都不对劲却无明显错误时的方法论。配套 页面：<a href="./debug-interfaces.html">debug-interfaces.md</a> 盘点约 93 个测试桩程序；<a href="./qemu-testing.html">qemu-testing.md</a> 覆盖 QEMU 特有行为；<a href="./debugging.html">debugging.md</a> 是简短入口。</p><h2 id="_1-串口提取" tabindex="-1">1. 串口提取 <a class="header-anchor" href="#_1-串口提取" aria-label="Permalink to &quot;1. 串口提取&quot;">​</a></h2><p>每一条启动行、panic 横幅与被捕获的 op 都镜像到 COM1 （115200 8N1，轮询）。串口是<em>权威</em>通道（VGA 尽力而为）。</p><p><strong>QEMU</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios          # -display none -serial mon:stdio -snapshot</span></span>
<span class="line"><span># or explicitly:</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512M -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1 \\</span></span>
<span class="line"><span>    -display none -serial mon:stdio          # interactive (monitor on Ctrl-A C)</span></span>
<span class="line"><span>qemu-system-x86_64 ... -serial file:boot.log # capture to a file</span></span>
<span class="line"><span>qemu-system-x86_64 ... -serial stdio -d int,cpu_reset -D qemu.log</span></span></code></pre></div><p>pexpect 测试装置使用带 <code>encoding=&quot;latin-1&quot;</code> 的 <code>-serial mon:stdio</code>，让每个字节都存活；提示符正则是 <code>(?:ush&gt;|oc&gt;)\\s</code>（用 <code>OC_PROMPT</code> 覆盖）。</p><p><strong>真实硬件</strong>：COM1 插针上接一个 USB-TTL 适配器。串口 tee 编码跟随 <code>serial_encoding</code> 设置（<code>utf8|gbk</code>，显示 op 17）—— 当你的终端是 GB2312 时代的控制台时设为 <code>gbk</code>。</p><h2 id="_2-读取内核日志环" tabindex="-1">2. 读取内核日志环 <a class="header-anchor" href="#_2-读取内核日志环" aria-label="Permalink to &quot;2. 读取内核日志环&quot;">​</a></h2><p>1024 项的环（<code>klog_grow()</code> 之前是 24 项引导环）无条件 记录一切；实时通道（串口 + 控制台）由实时级别（默认 INFO）把关。回放 op 对其展示内容应用活动过滤器。</p><p>行格式（环回放、<code>/var/log/kernel.log</code> 与实时通道中完全 一致）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[   12.345] WARN  net: link up (e1000)</span></span>
<span class="line"><span>[SSS.mmm]    LEVEL module: message</span></span></code></pre></div><ul><li>时间戳 = 自 <code>klog_init</code> 以来的秒.毫秒 （<code>core_timer_now_ms</code>；PIT 之前为 0.000），</li><li>级别是 DEBUG 0 / INFO 1 / WARN 2 / ERROR 3 / FATAL 4 之一（在列中渲染为 <code>DEBUG/INFO/WARN /ERROR/FATAL</code>），</li><li>模块是 12 字符标签（<code>net</code>、<code>health</code>、<code>ocire</code>、 <code>klogtest</code>、...）。</li></ul><p>用法表（应用 <code>dmesg</code>、<code>logcat</code>、<code>logctl</code>）：</p><table tabindex="0"><thead><tr><th>命令</th><th>语法</th><th>作用</th></tr></thead><tbody><tr><td><code>dmesg</code></td><td><code>dmesg [N]</code></td><td>经活动过滤器回放环尾（默认 30，1..1024 行）；页脚 <code>-- &lt;shown&gt; lines (ring &lt;count&gt;/1024, dropped &lt;d&gt;) --</code></td></tr><tr><td><code>logcat</code></td><td><code>logcat -l &lt;lvl&gt; -m &lt;mod&gt; -k &lt;key&gt; -t &lt;sec&gt; -n &lt;N&gt; [-f]</code></td><td>过滤回放；<code>-l</code> debug/info/warn/error/fatal 或 0-4，<code>-m</code> 模块精确匹配，<code>-k</code> 关键字子串，<code>-t</code> 秒截断，<code>-n</code> 条数；<code>-f</code> 以 10 Hz 轮询实时跟踪（ENTER 退出）</td></tr><tr><td><code>logctl status</code></td><td></td><td>环计数、丢弃数、实时级别 + 逐级掩码、文件字节数/轮转信息、过滤器状态</td></tr><tr><td><code>logctl level [-1..4]</code></td><td></td><td>设置实时级别（-1 静音实时通道；环仍记录）</td></tr><tr><td><code>logctl enable|disable &lt;level&gt;</code></td><td></td><td>逐级发射开关</td></tr><tr><td><code>logctl clear</code></td><td></td><td>重置环</td></tr><tr><td><code>logctl flush</code></td><td></td><td>把未同步条目追加到 <code>/var/log/kernel.log</code></td></tr><tr><td><code>logctl rotate</code></td><td></td><td>kernel.log -&gt; kernel.log.1（保留 3 份）</td></tr><tr><td><code>logctl threshold &lt;512..16777216&gt;</code></td><td></td><td>轮转阈值（默认 1048576）</td></tr><tr><td><code>logctl export [path]</code></td><td></td><td>转储到 <code>/var/log/kernel-export.log</code></td></tr><tr><td><code>logctl filter clear | [level] [module] [keyword]</code></td><td></td><td>设置/清除活动过滤器（&#39;-&#39; = 任意）；作用于实时通道与 dmesg/logcat 回放</td></tr><tr><td><code>logctl test</code></td><td></td><td>每级一行共 5 行，模块 <code>klogtest</code> —— 过滤器验证工具</td></tr></tbody></table><p>磁盘通道（<code>/var/log/kernel.log</code>，1 MiB 轮转 x3）是 <code>klog_on_mount()</code> 在首次 fs 挂载后安装的发射钩子；它追加 每条尚未同步的条目并自动轮转。IRQ 上下文的写方跳过 FILE 通道（推迟到下一个任务上下文写方/flush/定时器踢）。</p><h2 id="_3-崩溃证据" tabindex="-1">3. 崩溃证据 <a class="header-anchor" href="#_3-崩溃证据" aria-label="Permalink to &quot;3. 崩溃证据&quot;">​</a></h2><h3 id="_3-1-panic-横幅-报告中应附上的内容" tabindex="-1">3.1 panic 横幅（报告中应附上的内容） <a class="header-anchor" href="#_3-1-panic-横幅-报告中应附上的内容" aria-label="Permalink to &quot;3.1 panic 横幅（报告中应附上的内容）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*** KERNEL PANIC: &lt;reason&gt; [task=&lt;name&gt;] ***</span></span>
<span class="line"><span>kernel: Open Cube OS &lt;version&gt; (build 0x&lt;hex&gt;)</span></span>
<span class="line"><span>source: exception &lt;n&gt; (&lt;name&gt;) err=0x&lt;hex&gt;</span></span>
<span class="line"><span>&lt;task line&gt;</span></span>
<span class="line"><span>&lt;register dump: 4x4 grid r15..rax + rip/cs/ss/rflags/rsp/int/err [+ cr2] + cr3&gt;</span></span>
<span class="line"><span>&lt;traceback: rbp chain + stack scan&gt;</span></span>
<span class="line"><span>&lt;policy: HALT or REBOOT&gt;</span></span></code></pre></div><p>你可能见到的变体：<code>[KERNEL STACK OVERFLOW: exhausted, task=&lt;name&gt;]</code>（栈溢出归因）；<code>core dump: skipped in #DF mode</code>（#DF 在分发器深度被最小化处理，仅一条静态 串口行 —— 无记录、无转储、无刷洗，见 KNOWN_ISSUES）； <code>*** NESTED PANIC INSIDE PANIC - HALTING ***</code>； <code>*** CONTAINED: &lt;what&gt; - isolated, kernel continues ***</code> （某个 panic 处理程序认领了恢复）。</p><h3 id="_3-2-crashlog-——-32-槽位环" tabindex="-1">3.2 crashlog —— 32 槽位环 <a class="header-anchor" href="#_3-2-crashlog-——-32-槽位环" aria-label="Permalink to &quot;3.2 crashlog —— 32 槽位环&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; crashlog          # each entry:</span></span>
<span class="line"><span>[i] &lt;src-name&gt; ring=N err=0x.. rip=0x.. rsp=0x.. [cr2=0x..] [@&lt;rtc&gt;s | @tick=N] [task=&lt;name&gt;] [pid=N]</span></span>
<span class="line"><span>ush&gt; crashlog flush    # append all entries to /var/log/crash.log</span></span></code></pre></div><p>来源名：异常名（<code>#PF Page Fault</code>、...）或合成来源 —— PANIC 32 / WDT 33 / ASSERT 34 / CONTAINED 35 / STACKOVF 36。为空时：<code>crashlog: no exceptions recorded</code>。</p><h3 id="_3-3-dumpinfo-与-ocdump01-镜像" tabindex="-1">3.3 dumpinfo 与 OCDUMP01 镜像 <a class="header-anchor" href="#_3-3-dumpinfo-与-ocdump01-镜像" aria-label="Permalink to &quot;3.3 dumpinfo 与 OCDUMP01 镜像&quot;">​</a></h3><p><code>dumpinfo</code> 报告核心转储缓冲区状态。保存的 <code>/var/crash/core.dump</code> 以如下内容开头：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> magic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            /* &quot;OCDUMP01&quot; */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u32 hdr_len;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              /* sizeof(oc_dump_hdr_t) */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u32 image_len;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            /* total bytes captured */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u64 build;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                /* OC_KERNEL_BUILD */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         /* OC_RELEASE_VERSION */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> reason</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]; u64 jiffies; u64 rtc_epoch;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u64 cr3; u64 pte_count; u32 tid, pid; u32 ring; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> task</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u64 stack_base, stack_size, stack_rsp; u32 stack_copy_len; u32 regs_present;</span></span></code></pre></div><p>其后是寄存器（22 个 u64）、任务块、4 KiB 栈窗口与页表 扫描。完全没有文件系统时，前 2048 字节以十六进制转储到 串口。<code>crashtest dump</code> 不触发 panic 地捕获一个 —— 在 真正需要之前用它验证你的捕获接线。</p><h3 id="_3-4-读取寄存器快照" tabindex="-1">3.4 读取寄存器快照 <a class="header-anchor" href="#_3-4-读取寄存器快照" aria-label="Permalink to &quot;3.4 读取寄存器快照&quot;">​</a></h3><p>转储的 22 个 u64 是 <code>arch_irq_frame_t</code>（r15..rax、 int_no、error_code、rip、cs、rflags、rsp、ss）。按异常 类别：</p><table tabindex="0"><thead><tr><th>异常</th><th>要紧的字段</th><th>典型含义</th></tr></thead><tbody><tr><td>#PF (14)</td><td><code>cr2</code> = 故障地址；error_code bit0 (P)</td><td>P=0：不存在（NULL/野指针，或限制之内 RSP 以下的栈增长）；P=1：保护违例 —— 绝不重映射，是真实 bug；U/S 位指示环；I/D 位 = 取指（NX）</td></tr><tr><td>#GP (13)</td><td>error_code 选择子索引</td><td>坏描述符/特权 —— 经典的 ring-3 I/O 尝试（IOPB 拒绝所有端口）</td></tr><tr><td>#DE (0)、#OF (4)</td><td>rax/操作数</td><td>rip 处的除法/溢出</td></tr><tr><td>#UD (6)</td><td>rip</td><td>执行了垃圾 —— 查回溯的代码区间过滤</td></tr><tr><td>#DF (8)</td><td>rsp 相对任务栈窗口</td><td>rsp 位于/低于栈底 =&gt; 栈耗尽归因；#DF 只打印最小行</td></tr><tr><td>#DB/NMI/#BP (1/2/3)</td><td>-</td><td>在 IST2 上处理；ring-3 来源的 kill 在退出栈上运行</td></tr><tr><td>看门狗 (33)</td><td>任务行</td><td>布防状态下心跳饿死 15 秒</td></tr><tr><td>stackovf (36)</td><td>任务名</td><td>命中 kthread 守卫页</td></tr></tbody></table><p><code>rip</code> 落在某任务的守卫页内或其栈基之下，就是栈溢出的 铁证；回溯打印 rbp 链加上经 <code>looks_like_code</code> 过滤的 栈扫描候选。</p><h2 id="_4-静默失败方法论" tabindex="-1">4. 静默失败方法论 <a class="header-anchor" href="#_4-静默失败方法论" aria-label="Permalink to &quot;4. 静默失败方法论&quot;">​</a></h2><p>当没有 panic、没有横幅、没有错误行时 —— 自上而下过这架 梯子。</p><h3 id="_4-1-健康告警-客观状态" tabindex="-1">4.1 健康告警（客观状态） <a class="header-anchor" href="#_4-1-健康告警-客观状态" aria-label="Permalink to &quot;4.1 健康告警（客观状态）&quot;">​</a></h3><p><code>health</code> 打印 cpu/内存/任务/磁盘/网络，外加 <code>alarms:</code> 行。这三个位每秒采样、去重（每次越限一条 ERROR，指标 恢复时重新布防）：</p><table tabindex="0"><thead><tr><th>告警</th><th>触发</th><th>含义</th></tr></thead><tbody><tr><td><code>MEMORY&gt;90%</code></td><td><code>mem_used*100/mem_total &gt; 90</code></td><td>PMM+堆压力 —— 查 <code>mem</code>、<code>frag</code>、<code>heap</code></td></tr><tr><td><code>TASKS&gt;64</code></td><td>活动任务 &gt; 64</td><td>任务槽位泄漏 —— <code>ps</code>/<code>sched</code>，找未被收割的退出</td></tr><tr><td><code>CPU-LOCKED</code></td><td>连续 10 次采样忙碌 &gt;= 90%</td><td>自旋/钉死循环 —— <code>sched</code>、把嫌疑者 <code>nice</code> 降级</td></tr></tbody></table><h3 id="_4-2-日志环-不是实时控制台" tabindex="-1">4.2 日志环（不是实时控制台） <a class="header-anchor" href="#_4-2-日志环-不是实时控制台" aria-label="Permalink to &quot;4.2 日志环（不是实时控制台）&quot;">​</a></h3><p>即使实时级别或过滤器藏起了行，环也无条件记录： <code>logctl level 0</code>（打开实时门），然后 <code>dmesg 200</code>。 <code>logctl test</code> 证明流水线本身在工作。若某个&quot;什么都没做&quot; 的子系统在环中连 FATAL 都没有，它可能采用的是诚实跳过 约定（4.5）而非记日志。</p><h3 id="_4-3-kcap-陷阱-消失的输出" tabindex="-1">4.3 kcap 陷阱（消失的输出） <a class="header-anchor" href="#_4-3-kcap-陷阱-消失的输出" aria-label="Permalink to &quot;4.3 kcap 陷阱（消失的输出）&quot;">​</a></h3><p><strong>本代码库中最常见的单一静默失败原因。</strong> 当一个 L1SVC 捕获处于激活状态时，捕获钩子<em>就是</em>控制台钩子：字符收集 进调用方缓冲区，帧缓冲与串口 tee 两者都被压制。后果：</p><ul><li>一个内部触发实时输出的被捕获 op（嵌套的实时会话、 sleep 停驻、本应打到串口的 klog FATAL）看起来就像 系统控制台失声。</li><li>历史上被现场抓住的案例：被捕获的 <code>power sleep</code> 在整个 停驻期间装着捕获钩子，在 OCIRE 监督启动期间吞掉了 每一条控制台行；<code>sshd</code> 不得不改为直连路由，好让 <code>net_sshd_log</code> 实时到达控制台。</li><li>规则：停驻或占有实时会话的 op 直连路由 （<code>out[0]=0; return fn(arg);</code>）；只有一次性文本渲染器 以捕获方式运行。如果你在添加 op 而其输出&quot;消失&quot;，先查 路由方式（<a href="./writing-services.html">writing-services.md</a>）。</li></ul><h3 id="_4-4-返回值约定" tabindex="-1">4.4 返回值约定 <a class="header-anchor" href="#_4-4-返回值约定" aria-label="Permalink to &quot;4.4 返回值约定&quot;">​</a></h3><ul><li>系统调用成功返回 <code>&gt;= 0</code>、出错返回负值（多数路径为 <code>-1</code>）；<code>SYS_L1SVC</code> 对任何<em>已路由</em>调用都返回 0 —— 操作自身的失败文本在 <code>out</code> 之内（见 <a href="./syscall-reference.html">syscall-reference.md</a> 第 1.5/4 节）。</li><li>驱动/块/nic op 成功返回 0（或正的字节数）、出错返回 负值。</li><li>若包装程序打印 <code>&lt;name&gt;: svc_call_failed</code>，说明<em>类别 或 op 没有路由成功</em> —— op 编号打错、纯内核服务，或 （cat 18）非守卫调用方被拒绝： <code>ocire: refused (guard-only channel)</code>。</li></ul><h3 id="_4-5-诚实跳过-模式" tabindex="-1">4.5 &quot;诚实跳过&quot;模式 <a class="header-anchor" href="#_4-5-诚实跳过-模式" aria-label="Permalink to &quot;4.5 &quot;诚实跳过&quot;模式&quot;">​</a></h3><p>代码树刻意区分 FAIL 与 SKIP。认出这些字符串，不要把它们 当 bug 追：</p><ul><li><code>... =&gt; SKIPPED</code>（例如 <code>[sample_rate_test] no sound cards registered =&gt; SKIPPED</code>）—— 前置条件缺失，测试 未运行。</li><li><code>honest FAIL</code>（例如 <code>oneshot: arm failed (honest FAIL)</code>）—— 操作确实被尝试并被拒绝。</li><li><code>: SKIP - see the dedicated halt session</code>（halt/reboot 测试 —— 破坏性，刻意不观察活体停机）。</li><li><code>watchdog hw: none (no WDAT table, no Intel TCO LPC)</code> —— 探测诚实地报告缺席（默认 <code>pc</code> 机型没有 TCO； 用 q35）。</li><li>QEMU 下的 <code>wifi scan</code> 打印诚实的 &quot;no radio&quot; 输出。</li><li><code>ocire: embed inactive (normal boot)</code> —— cat 18 在 GRUB 启动上休眠；这是正确行为。</li><li><code>DesignWare: not present on this platform (honest skip)</code>。</li></ul><h3 id="_4-6-死锁-vs-挂死" tabindex="-1">4.6 死锁 vs. 挂死 <a class="header-anchor" href="#_4-6-死锁-vs-挂死" aria-label="Permalink to &quot;4.6 死锁 vs. 挂死&quot;">​</a></h3><ul><li>软看门狗（15 秒，槽位 0 &quot;system-heartbeat&quot;）只在 <em>已布防且被饿死</em>时以来源 WDT panic；shell 行编辑器每 次按键都踢它 —— 一台还能应答按键的机器在调度器层面 是活的。</li><li><code>ps</code>/<code>sched</code>：卡在 TASK_BLOCKED 且无等待者的任务就是 你的候选者；<code>syncstat</code> 显示原语操作计数器。</li><li>启动状态监视器的 <code>/HANGAT</code> 注入（见下）端到端演练 刻意挂死路径。</li></ul><h2 id="_5-故障注入工具" tabindex="-1">5. 故障注入工具 <a class="header-anchor" href="#_5-故障注入工具" aria-label="Permalink to &quot;5. 故障注入工具&quot;">​</a></h2><h3 id="_5-1-crashtest-——-8-种模式" tabindex="-1">5.1 crashtest —— 8 种模式 <a class="header-anchor" href="#_5-1-crashtest-——-8-种模式" aria-label="Permalink to &quot;5.1 crashtest —— 8 种模式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: crashtest panic|exc|pf|assert|wd|ovf|dump|policy [halt|reboot]</span></span>
<span class="line"><span>  panic   : kernel_panic() direct</span></span>
<span class="line"><span>  exc     : ring-0 #UD exception</span></span>
<span class="line"><span>  pf      : ring-0 unmapped-address write fault</span></span>
<span class="line"><span>  assert  : OC_ASSERT(0)</span></span>
<span class="line"><span>  wd      : forced watchdog timeout</span></span>
<span class="line"><span>  ovf     : kernel stack overflow (guard page)</span></span>
<span class="line"><span>  dump    : capture a core dump without panicking</span></span>
<span class="line"><span>  policy  : show/set the after-panic policy</span></span></code></pre></div><ul><li><code>exc</code> 执行 <code>__asm__ volatile(&quot;.byte 0x0F, 0x0B\\n&quot;)</code> （#UD）。</li><li><code>pf</code> 向 0x700000000000 写入（PML4[224]，保证不存在 —— C 的 NULL 解引用行不通：UB 会折叠成 ud2 而且页 0 是 恒等映射的）。</li><li><code>panic|exc|pf|assert|wd|ovf</code> 会真的让内核崩溃 （v2.2.0 行为）；<code>policy</code>/<code>dump</code>/用法是安全的。未知 变体：<code>crashtest: unknown variant &#39;x&#39; (try: crashtest help)</code>。</li></ul><p>在真实故障之前，用 <code>crashtest dump</code> + <code>dumpinfo</code> + <code>crashlog</code> 证明你的证据链；用会崩溃的模式测试 panic 策略与 OCBL/OCIRE 继电器。</p><h3 id="_5-2-msitest-——-msi-注入" tabindex="-1">5.2 msitest —— MSI 注入 <a class="header-anchor" href="#_5-2-msitest-——-msi-注入" aria-label="Permalink to &quot;5.2 msitest —— MSI 注入&quot;">​</a></h3><p><code>msitest</code>（diag op 21）触发真实的 MSI/MSI-X 中断投递 （LAPIC 向量 0x30..0x6F）—— 用它独立于设备流量证明 MSI 路径（使能、向量注册、EOI）。</p><h3 id="_5-3-hangat-——-启动阶段挂死注入器" tabindex="-1">5.3 /HANGAT —— 启动阶段挂死注入器 <a class="header-anchor" href="#_5-3-hangat-——-启动阶段挂死注入器" aria-label="Permalink to &quot;5.3 /HANGAT —— 启动阶段挂死注入器&quot;">​</a></h3><p>内核命令行 <code>oc.hang=&lt;stage&gt;</code> 在写完指定启动状态阶段 + 布防看门狗<em>之后</em>停住启动，演练真实的 6300ESB 继电器链 （阶段监视器写入、心跳停止、硬件复位、OCBL 判定、记录 路由到 OCIRE）。<code>oc.stmon=off</code> 关闭整个状态监视器。 阶段名来自 <code>ocst_stage_name</code>：BOOT、KM_AIN_ENTERED、 SCHED_READY、DRIVERS_READY、SERVICES_READY、 L1_LAUNCHED、L1_READY。</p><h3 id="_5-4-看门狗测试注入器" tabindex="-1">5.4 看门狗测试注入器 <a class="header-anchor" href="#_5-4-看门狗测试注入器" aria-label="Permalink to &quot;5.4 看门狗测试注入器&quot;">​</a></h3><p><code>watchdog test kill|panic|log</code> 孵化一个 <code>wd-starve</code> kthread（优先级 15），把自己注册为受监视 3 秒且从不 喂狗 —— &quot;expect the policy in 3 s&quot;（按注册的策略： 任务被 kill / 内核 panic / ERROR 日志）。</p><h2 id="_6-宿主侧工具" tabindex="-1">6. 宿主侧工具 <a class="header-anchor" href="#_6-宿主侧工具" aria-label="Permalink to &quot;6. 宿主侧工具&quot;">​</a></h2><ul><li><code>build/opencube_base.elf</code> 是 <code>strip</code> 之前的符号载体 （流水线以 <code>-g</code> 链接，然后 strip 最终 ELF）。</li><li>gdb：<code>qemu ... -s -S</code>，然后 <code>target remote localhost:1234</code>、<code>break kmain</code>、<code>continue</code>。</li><li><code>-d int,cpu_reset,guest_errors -D qemu.log</code> 记录中断、 复位与错误。</li><li><code>make test</code> 运行宿主单元套件（加密向量、tar、gzip、 MB2 解析、CUBIC、block-512 门禁、...）—— 比启动循环 的迭代快得多；若干套件在本地使用 ASAN。</li><li>可重现构建意味着两次复现的崩溃是相同字节 —— 多次 尝试之间不存在海森堡式构建差异 （<code>make reproducible-check</code>）。</li></ul>`,61)])])}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
